-- Mirrors applied Supabase migration 20260925084514. Review-first HR operations extension.
create table if not exists hr.employment_terms (id uuid primary key default gen_random_uuid(),employee_id uuid not null,company_id uuid not null,effective_from date not null,effective_to date,pay_basis text not null check(pay_basis in ('annual','hourly')),base_rate_gbp numeric(13,4) not null check(base_rate_gbp>=0),contracted_hours_weekly numeric(7,2),working_pattern text not null default 'regular' check(working_pattern in ('regular','irregular','part_year')),tax_code text,tax_basis text not null default 'cumulative' check(tax_basis in ('cumulative','week1_month1')),ni_category text,pension_employee_rate numeric(7,4),pension_employer_rate numeric(7,4),student_loan_plan text,postgraduate_loan boolean not null default false,foreign key(employee_id,company_id) references hr.employees(id,company_id) on delete restrict,check(effective_to is null or effective_to>=effective_from));
create table if not exists hr.shifts (id uuid primary key default gen_random_uuid(),employee_id uuid not null,company_id uuid not null,starts_at timestamptz not null,ends_at timestamptz not null,unpaid_break_minutes int not null default 0 check(unpaid_break_minutes>=0),status text not null default 'scheduled' check(status in ('scheduled','completed','cancelled')),foreign key(employee_id,company_id) references hr.employees(id,company_id) on delete restrict,check(ends_at>starts_at));
create table if not exists hr.compliance_tasks (id uuid primary key default gen_random_uuid(),company_id uuid not null references hr.employers(company_id) on delete restrict,employee_id uuid,task_type text not null,title text not null,due_at timestamptz,status text not null default 'open' check(status in ('open','in_review','completed','dismissed')),guidance_version text,human_review_required boolean not null default true,created_at timestamptz not null default now(),foreign key(employee_id,company_id) references hr.employees(id,company_id) on delete restrict);
create table if not exists hr.payroll_config_versions (id uuid primary key default gen_random_uuid(),company_id uuid not null references hr.employers(company_id) on delete restrict,tax_year text not null,effective_from date not null,effective_to date,source_name text not null,source_url text not null,config jsonb not null,verified_at timestamptz,verified_by uuid,status text not null default 'testing' check(status in ('testing','verified','retired')),unique(company_id,tax_year,effective_from),check(effective_to is null or effective_to>=effective_from));
create table if not exists hr.payroll_items (id uuid primary key default gen_random_uuid(),payroll_run_id uuid not null references hr.payroll_runs(id) on delete restrict,employee_id uuid not null,company_id uuid not null,gross_pay numeric(13,2) not null default 0,taxable_pay numeric(13,2) not null default 0,paye_tax numeric(13,2) not null default 0,employee_ni numeric(13,2) not null default 0,employer_ni numeric(13,2) not null default 0,employee_pension numeric(13,2) not null default 0,employer_pension numeric(13,2) not null default 0,student_loan numeric(13,2) not null default 0,postgraduate_loan numeric(13,2) not null default 0,other_deductions numeric(13,2) not null default 0,net_pay numeric(13,2) not null default 0,total_employer_cost numeric(13,2) not null default 0,calculation_detail jsonb not null default '{}'::jsonb,validation_status text not null default 'unvalidated' check(validation_status in ('unvalidated','valid','invalid')),foreign key(employee_id,company_id) references hr.employees(id,company_id) on delete restrict,unique(payroll_run_id,employee_id));
create table if not exists hr.pension_assessments (id uuid primary key default gen_random_uuid(),employee_id uuid not null,company_id uuid not null,assessed_on date not null,assessment_status text not null check(assessment_status in ('eligible','non_eligible_jobholder','entitled_worker','postponed','opted_out','re_enrol_due')),qualifying_earnings numeric(13,2),employee_contribution numeric(13,2),employer_contribution numeric(13,2),provider text,submission_status text not null default 'manual_review' check(submission_status in ('manual_review','prepared','recorded')),foreign key(employee_id,company_id) references hr.employees(id,company_id) on delete restrict);
create table if not exists hr.payslip_versions (id uuid primary key default gen_random_uuid(),payroll_item_id uuid not null references hr.payroll_items(id) on delete restrict,employee_id uuid not null,company_id uuid not null,version int not null default 1 check(version>0),storage_path text,status text not null default 'draft' check(status in ('draft','approved','issued','superseded')),approved_by uuid,approved_at timestamptz,created_at timestamptz not null default now(),foreign key(employee_id,company_id) references hr.employees(id,company_id) on delete restrict,unique(payroll_item_id,version),check(status not in ('approved','issued') or approved_at is not null));
create table if not exists hr.external_submission_drafts (id uuid primary key default gen_random_uuid(),company_id uuid not null references hr.employers(company_id) on delete restrict,employee_id uuid,submission_type text not null check(submission_type in ('hmrc_fps','hmrc_eps','ukvi_worker_change','ukvi_organisation_change','pension')),payload jsonb not null default '{}'::jsonb,status text not null default 'draft' check(status in ('draft','reviewed','sandbox_tested','cancelled')),live_submission_allowed boolean not null default false check(live_submission_allowed=false),created_at timestamptz not null default now(),foreign key(employee_id,company_id) references hr.employees(id,company_id) on delete restrict);
create table if not exists hr.document_metadata (id uuid primary key default gen_random_uuid(),employee_id uuid not null,company_id uuid not null,storage_path text not null unique,document_type text not null,retention_until date,deletion_status text not null default 'retained' check(deletion_status in ('retained','deletion_review','deleted')),created_at timestamptz not null default now(),foreign key(employee_id,company_id) references hr.employees(id,company_id) on delete restrict);
create index if not exists hr_terms_effective on hr.employment_terms(company_id,employee_id,effective_from desc);create index if not exists hr_shifts_time on hr.shifts(company_id,starts_at);create index if not exists hr_tasks_due on hr.compliance_tasks(company_id,status,due_at);create index if not exists hr_payroll_items_company on hr.payroll_items(company_id,payroll_run_id);create index if not exists hr_pension_employee on hr.pension_assessments(company_id,employee_id,assessed_on desc);
revoke all on all tables in schema hr from public,anon,authenticated;grant all on all tables in schema hr to service_role;grant usage,select on all sequences in schema hr to service_role;
alter table hr.employment_terms enable row level security;alter table hr.shifts enable row level security;alter table hr.compliance_tasks enable row level security;alter table hr.payroll_config_versions enable row level security;alter table hr.payroll_items enable row level security;alter table hr.pension_assessments enable row level security;alter table hr.payslip_versions enable row level security;alter table hr.external_submission_drafts enable row level security;alter table hr.document_metadata enable row level security;